.toggle button.active { background: var(--surface); box-shadow: var(--shadow); }

.faq-item { border-top: 1px solid var(--border); }
.faq-q { width: 100%; text-align: left; border: 0; background: transparent; padding: .9rem .1rem; font-weight: 700; cursor: pointer; }
.faq-a { display: none; color: var(--muted); padding: 0 0 .9rem; }
